PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry swish_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 N
)
{
    .reg .pred %p0, %p1;
    .reg .u32 %tid, %blockIdx, %blockDim, %gridDim, %idx, %stride;
    .reg .u64 %in_ptr, %out_ptr, %in_addr, %out_addr;
    .reg .b16 %hval;
    .reg .f32 %fval, %tmp, %exp, %denom, %inv, %out_f;

    // Load kernel parameters
    ld.param.u64 %in_ptr, [input_ptr];
    ld.param.u64 %out_ptr, [output_ptr];
    ld.param.u32 %N, [N];

    // Thread identifiers
    mov.u32 %tid,      %tid.x;
    mov.u32 %blockIdx, %ctaid.x;
    mov.u32 %blockDim, %ntid.x;
    mov.u32 %gridDim,  %nctaid.x;

    // Global linear index for this thread
    mad.lo.u32 %idx, %blockIdx, %blockDim, %tid;

    // Total stride for the grid‑wide loop
    mul.lo.u32 %stride, %gridDim, %blockDim;

    // If first index already out of bounds, skip everything
    setp.ge.u32 %p0, %idx, %N;
    @%p0 bra DONE;

LOOP:
    // ---------- Load fp16 element ----------
    mul.wide.u32 %in_addr, %idx, 2;          // byte offset (2 bytes per half)
    add.u64 %in_addr, %in_ptr, %in_addr;
    ld.global.b16 %hval, [%in_addr];
    cvt.f32.f16 %fval, %hval;                // promote to fp32 for computation

    // ---------- Compute sigmoid(x) ----------
    // tmp = -x * log2(e)
    mul.f32 %tmp, %fval, -1.4426950408889634;
    // exp = 2^{tmp}  ≈  exp(-x)
    ex2.approx.f32 %exp, %tmp;
    // denom = 1 + exp
    add.f32 %denom, %exp, 1.0;
    // inv = 1 / denom   (approximate reciprocal)
    rcp.approx.f32 %inv, %denom;
    // sigmoid = inv
    // ---------- Multiply by original x ----------
    mul.f32 %out_f, %fval, %inv;             // y = x * sigmoid(x)

    // ---------- Store fp16 result ----------
    cvt.rn.f16.f32 %hval, %out_f;            // round‑to‑nearest fp16
    mul.wide.u32 %out_addr, %idx, 2;
    add.u64 %out_addr, %out_ptr, %out_addr;
    st.global.b16 [%out_addr], %hval;

    // ---------- Advance to next element ----------
    add.u32 %idx, %idx, %stride;
    setp.lt.u32 %p1, %idx, %N;
    @%p1 bra LOOP;

DONE:
    ret;
}
"""

class ModelNew:
    """
    Drop‑in replacement for the reference PyTorch model.
    Uses a custom PTX kernel to compute Swish activation on fp16 tensors.
    """
    def __init__(self):
        # Load the PTX module via the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply Swish activation using the PTX kernel.

        Args:
            x (torch.Tensor): fp16 CUDA tensor of arbitrary shape.

        Returns:
            torch.Tensor: fp16 CUDA tensor with Swish applied, same shape as x.
        """
        if not x.is_cuda:
            raise RuntimeError("Input tensor must be on CUDA device")
        if x.dtype != torch.float16:
            raise RuntimeError("Input tensor must be torch.float16")

        out = torch.empty_like(x)

        # Total number of elements
        N = x.numel()

        # Kernel launch configuration
        block_dim = (256, 1, 1)
        grid_dim = ((N + block_dim[0] - 1) // block_dim[0], 1, 1)

        # Argument list: input pointer, output pointer, element count
        args = [x.data_ptr(), out.data_ptr(), N]

        # Launch the PTX kernel
        ptx_launch(self.module, "swish_kernel", grid_dim, block_dim, args)

        return out
